<?php
require_once 'config.php'; require_login(); $pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST' && is_admin()){verify_csrf();$st=$pdo->prepare("INSERT INTO projects(financial_year_id,title,tender_id,project_head,start_date,duration_days) VALUES(?,?,?,?,?,?)");$st->execute([$_POST['financial_year_id'],trim($_POST['title']),trim($_POST['tender_id']),trim($_POST['project_head']),$_POST['start_date'],max(1,(int)$_POST['duration_days'])]);flash('Project created. Assign users and permissions from Users & permissions.');redirect('projects.php');}
if(is_admin())$projects=$pdo->query("SELECT p.*,f.name fy FROM projects p JOIN financial_years f ON f.id=p.financial_year_id ORDER BY p.id DESC")->fetchAll();else{$st=$pdo->prepare("SELECT p.*,f.name fy FROM projects p JOIN financial_years f ON f.id=p.financial_year_id JOIN project_assignments a ON a.project_id=p.id WHERE a.user_id=? AND a.view_project=1 ORDER BY p.id DESC");$st->execute([user()['id']]);$projects=$st->fetchAll();}
$years=$pdo->query("SELECT * FROM financial_years ORDER BY start_date DESC")->fetchAll();include 'layout_top.php';?>
<section class="page-title"><div><span class="eyebrow">প্রকল্প তালিকা</span><h1>প্রকল্পসমূহ</h1><p>প্রকল্পের সময়সীমা, দরপত্রের তথ্য ও দায়িত্ব পরিচালনা করুন।</p></div></section>
<?php if(is_admin()):?><section class="panel"><div class="panel-head"><h2>নতুন প্রকল্প তৈরি</h2></div><?php if(!$years):?><p class="notice error">আগে একটি অর্থবছর তৈরি করুন।</p><?php else:?><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div><label>প্রকল্পের নাম</label><input name="title" required></div><div><label>দরপত্র আইডি</label><input name="tender_id" required></div><div><label>অর্থবছর</label><select name="financial_year_id" required><?php foreach($years as $y):?><option value="<?=$y['id']?>"><?=e($y['name'])?></option><?php endforeach;?></select></div><div><label>প্রকল্প প্রধান</label><input name="project_head"></div><div><label>শুরুর তারিখ</label><input type="date" name="start_date" required></div><div><label>মেয়াদ (দিন)</label><input type="number" min="1" name="duration_days" value="30" required></div><button class="btn primary">নতুন প্রকল্প তৈরি</button></form><?php endif;?></section><?php endif;?>
<section class="panel"><div class="panel-head"><h2>প্রকল্পের তালিকা</h2><span class="muted"><?=count($projects)?> প্রকল্প</span></div><div class="table-wrap"><table><thead><tr><th>Project</th><th>দরপত্র আইডি</th><th>অর্থবছর</th><th>Start</th><th>Duration</th><th>Status</th></tr></thead><tbody><?php foreach($projects as $p):?><tr><td><b><?=e($p['title'])?></b><small class="subline">Head: <?=e($p['project_head']?:'Not assigned')?></small></td><td><?=e($p['tender_id'])?></td><td><?=e($p['fy'])?></td><td><?=e($p['start_date'])?></td><td><?=e($p['duration_days'])?> days</td><td><span class="status <?=$p['status']?>"><?=e(ucfirst($p['status']))?></span></td></tr><?php endforeach;?><?php if(!$projects):?><tr><td colspan="6" class="empty">কোনো প্রকল্প পাওয়া যায়নি.</td></tr><?php endif;?></tbody></table></div></section><?php include 'layout_bottom.php';?>
